"""Relogio, sleeper, rng e ids falsos para testes deterministicos (RNF-08)."""
from __future__ import annotations

import random
from datetime import datetime, timedelta, timezone


class FakeClock:
    def __init__(self, start: datetime | None = None):
        self._now = start or datetime(2026, 11, 9, 10, 0, 0, tzinfo=timezone(timedelta(hours=-3)))
        self._mono = 1000.0

    def now(self) -> datetime:
        return self._now

    def monotonic(self) -> float:
        return self._mono

    def advance(self, seconds: float) -> None:
        self._mono += seconds
        self._now += timedelta(seconds=seconds)


class FakeSleeper:
    def __init__(self, clock: FakeClock):
        self.clock = clock
        self.calls: list[float] = []

    async def sleep(self, seconds: float) -> None:
        self.calls.append(seconds)
        self.clock.advance(seconds)


class SeededRng(random.Random):
    def __init__(self, seed: int = 7):
        super().__init__(seed)


class SeqIds:
    def __init__(self):
        self._q = 0
        self._r = 0

    def new_message_id(self, conversation_id: str, seq: int, direction: str) -> str:
        return f"m_{conversation_id}_{seq:04d}_{direction}"

    def new_quote_id(self) -> str:
        self._q += 1
        return f"q-{self._q:04d}"

    def new_run_id(self) -> str:
        self._r += 1
        return f"run-test-{self._r:03d}"
