import pytest

from autoseguro_agent.config import ConfigError, Settings

pytestmark = [pytest.mark.unit, pytest.mark.req("RNF-11")]


def test_defaults():
    s = Settings.from_env({})
    assert s.quote_base_url == "http://localhost:8000"
    assert s.quote_timeout_s == 4.0
    assert s.quote_max_attempts == 4
    assert s.quote_backoff_base_s == 0.5
    assert s.quote_total_budget_s == 20
    assert s.reask_limit == 2 and s.objection_limit == 2
    assert s.idle_timeout_s == 86400
    assert s.llm_enabled is False and s.llm_rewrite is False
    assert s.ollama_url == "http://localhost:11434"
    assert s.ollama_model == "llama3.1:8b"
    assert s.llm_timeout_s == 20 and s.llm_seed == 42
    assert s.log_dir == "logs" and s.log_level == "info"


def test_override():
    s = Settings.from_env({
        "AGENT_QUOTE_TIMEOUT_S": "1.5", "AGENT_QUOTE_MAX_ATTEMPTS": "3",
        "AGENT_LLM_ENABLED": "true", "AGENT_QUOTE_BASE_URL": "http://x:9/",
    })
    assert s.quote_timeout_s == 1.5 and s.quote_max_attempts == 3
    assert s.llm_enabled is True and s.quote_base_url == "http://x:9"


@pytest.mark.parametrize("name,val", [
    ("AGENT_QUOTE_TIMEOUT_S", "0"), ("AGENT_QUOTE_TIMEOUT_S", "abc"),
    ("AGENT_QUOTE_MAX_ATTEMPTS", "0"), ("AGENT_QUOTE_MAX_ATTEMPTS", "11"),
    ("AGENT_QUOTE_BACKOFF_BASE_S", "-1"), ("AGENT_QUOTE_TOTAL_BUDGET_S", "0"),
    ("AGENT_REASK_LIMIT", "-1"), ("AGENT_OBJECTION_LIMIT", "0"),
    ("AGENT_IDLE_TIMEOUT_S", "0"), ("AGENT_LLM_ENABLED", "talvez"),
    ("AGENT_QUOTE_BASE_URL", "localhost"), ("AGENT_LOG_LEVEL", "verbose"),
    ("AGENT_LLM_SEED", "x"),
])
def test_invalid_fails_fast_with_name(name, val):
    with pytest.raises(ConfigError) as ei:
        Settings.from_env({name: val})
    assert name in str(ei.value)
