"""RFC0001-T2: R$ so em presentation."""
import re
from pathlib import Path

import pytest

pytestmark = [pytest.mark.unit, pytest.mark.req("RF-10", "RF-11", "RNF-03")]

ROOT = Path(__file__).resolve().parents[2] / "src" / "autoseguro_agent"


def test_currency_symbol_only_in_presentation():
    offenders = []
    for py in ROOT.rglob("*.py"):
        rel = py.relative_to(ROOT).parts
        if rel[0] == "presentation":
            continue
        text = py.read_text(encoding="utf-8")
        # permitido em padroes/guardas que apenas detectam R$ (nao formatam)
        for ln, line in enumerate(text.splitlines(), 1):
            if "R$" in line and not re.search(r"(re\.|Pattern|compile|\"\"\"|#|'R\\\$'|r\"|r')", line):
                offenders.append(f"{py.name}:{ln}")
    assert not offenders, offenders
