"""RFC0001-T1: fronteiras de importacao entre modulos."""
import ast
from pathlib import Path

import pytest

pytestmark = [pytest.mark.unit, pytest.mark.req("RNF-07", "RNF-08")]

ROOT = Path(__file__).resolve().parents[2] / "src" / "autoseguro_agent"
PKG = "autoseguro_agent"
LEVEL = {
    "contracts": 0, "config": 1, "privacy": 1,
    "observability": 2, "llm": 2, "quote": 2, "policy": 2,
    "extraction": 3, "presentation": 3,
    "conversation": 4, "channels": 5,
}


def _imports(path: Path):
    tree = ast.parse(path.read_text(encoding="utf-8"))
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            if node.level:  # relativo: resolve para o pacote de primeiro nivel
                parts = path.relative_to(ROOT).with_suffix("").parts
                base = list(parts[: len(parts) - 1]) if node.level == 1 else list(
                    parts[: len(parts) - node.level])
                mod = ".".join(base + ([node.module] if node.module else []))
                if node.level == 1 and not node.module:
                    for a in node.names:
                        yield (".".join(base + [a.name])).split(".")[0] or a.name
                    continue
                top = mod.split(".")[0] if mod else (node.names[0].name)
                yield top
            elif node.module and node.module.startswith(PKG + "."):
                yield node.module.split(".")[1]
            elif node.module == PKG:
                for a in node.names:
                    yield a.name
        elif isinstance(node, ast.Import):
            for a in node.names:
                if a.name.startswith(PKG + "."):
                    yield a.name.split(".")[1]


def _module_of(path: Path) -> str:
    rel = path.relative_to(ROOT).parts
    return rel[0].removesuffix(".py")


def test_levels_and_forbidden_edges():
    violations = []
    for py in ROOT.rglob("*.py"):
        mod = _module_of(py)
        if mod not in LEVEL:
            continue  # __init__, __main__
        for dep in set(_imports(py)):
            if dep not in LEVEL or dep == mod:
                continue
            if LEVEL[dep] >= LEVEL[mod]:
                violations.append(f"{py.name}: {mod} -> {dep}")
            if mod in ("policy", "quote") and dep == "llm":
                violations.append(f"{py.name}: {mod} nao pode importar llm")
    assert not violations, violations


def test_contracts_has_no_internal_imports():
    for py in (ROOT / "contracts").rglob("*.py"):
        for dep in _imports(py):
            assert dep in ("contracts",), f"{py.name} importa {dep}"
