        raise MalformedResponse(f"{name}: numero esperado")
    d = Decimal(str(v)) if isinstance(v, (int, float)) else v
    if not d.is_finite():
        raise MalformedResponse(f"{name}: valor nao finito")
    if isinstance(v, float) and not math.isfinite(v):
        raise MalformedResponse(f"{name}: valor nao finito")
    return d


def _str_list(v: Any, name: str, *, non_empty: bool) -> tuple[str, ...]:
    if not isinstance(v, list) or any(not isinstance(i, str) for i in v):
        raise MalformedResponse(f"{name}: lista de strings esperada")
    if non_empty and not v:
        raise MalformedResponse(f"{name}: lista vazia")
    return tuple(v)


def parse_response(payload: Any, requested_plan: str) -> QuoteResponse:
    if not isinstance(payload, dict):
        raise MalformedResponse("corpo nao e objeto")
