        raise MalformedResponse("plano_id diferente do pedido")
    nome = payload.get("plano_nome")
    if not isinstance(nome, str) or not nome.strip():
        raise MalformedResponse("plano_nome ausente")
    premio = _num(payload.get("premio_mensal"), "premio_mensal")
    if premio <= 0:
        raise MalformedResponse("premio_mensal deve ser > 0")
    franquia = _num(payload.get("franquia"), "franquia")
    if franquia < 0:
        raise MalformedResponse("franquia negativa")
    coberturas = _str_list(payload.get("coberturas"), "coberturas", non_empty=True)
    car = payload.get("carencia")
    if not isinstance(car, dict):
        raise MalformedResponse("carencia ausente")
    dias = car.get("dias")
    if isinstance(dias, bool) or not isinstance(dias, int) or dias < 0:
        raise MalformedResponse("carencia.dias invalido")
    obs = car.get("observacao")
    if not isinstance(obs, str):
        raise MalformedResponse("carencia.observacao ausente")
    carencia = Carencia(_str_list(car.get("coberturas"), "carencia.coberturas", non_empty=False),
                        dias, obs)
    if payload.get("moeda") != "BRL":
        raise MalformedResponse("moeda diferente de BRL")
    pro_rata = None
    pr = payload.get("primeiro_pagamento_pro_rata")
    if pr is not None:
        if not isinstance(pr, dict):
            raise MalformedResponse("pro_rata invalido")
        dm, dc = pr.get("dias_no_mes"), pr.get("dias_cobrados")
        for n, v in (("dias_no_mes", dm), ("dias_cobrados", dc)):
            if isinstance(v, bool) or not isinstance(v, int):
                raise MalformedResponse(f"pro_rata.{n} invalido")
        if not 28 <= dm <= 31 or not 1 <= dc <= dm:
            raise MalformedResponse("pro_rata fora de faixa")
        vp = _num(pr.get("valor_primeiro_pagamento"), "valor_primeiro_pagamento")
        if vp <= 0 or vp > premio:
            raise MalformedResponse("valor_primeiro_pagamento incoerente")
        pro_rata = ProRata(dm, dc, vp)
    return QuoteResponse(plano_id, nome, premio, franquia, coberturas, carencia, "BRL", pro_rata)


def _json(body: Optional[bytes]) -> Any:
    if not body:
        raise ValueError("vazio")
    return json.loads(body, parse_float=Decimal)


def classify(status: Optional[int], body: Optional[bytes], exc: Optional[BaseException],
             requested_plan: str = "") -> Classification:
    if exc is not None:
        return Classification("transient", failure_kind=getattr(exc, "failure_kind", "network"))
    assert status is not None
    if status == 200:
        try:
            resp = parse_response(_json(body), requested_plan)
        except (ValueError, MalformedResponse):
            return Classification("transient", "malformed_200", status)
        return Classification("ok", None, status, response=resp)
    if status >= 500:
        return Classification("transient", "http_5xx", status)
    if status in (408, 429):
        return Classification("transient", "http_retryable", status)
    if status == 422:
        try:
            data = _json(body)
        except ValueError:
            return Classification("client_error", "unknown_422", status)
        if isinstance(data, dict):
            if data.get("error") == "cotacao_recusada" and isinstance(data.get("motivo"), str):
                return Classification("refused", None, status, refusal_reason=data["motivo"])
            if "detail" in data:
                return Classification("client_error", "validation_422", status)
        return Classification("client_error", "unknown_422", status)
    if status == 400:
        return Classification("client_error", "payload_invalido", status)
    return Classification("client_error", f"http_{status}", status)
