"""Cliente resiliente da POST /quote (RFC 0002, ADR 0011 a 0014)."""
from __future__ import annotations

import asyncio
from typing import Callable, Optional

import httpx

from ..config import Settings
from ..contracts import (
    AttemptRecord,
    Clock,
    IdGenerator,
    QuoteKind,
    QuoteRequest,
    QuoteResult,
    Rng,
    Sleeper,
)
from .classify import Classification, classify
from .validation import validate_request

MIN_REMAINING_S = 0.5
OnAttempt = Callable[[AttemptRecord], None]


class QuoteClient:
    def __init__(self, settings: Settings, *, transport: Optional[httpx.AsyncBaseTransport] = None,
                 clock: Clock, sleeper: Sleeper, rng: Rng, ids: IdGenerator,
                 on_attempt: Optional[OnAttempt] = None):
        self._s = settings
        self._transport = transport
        self._clock = clock
        self._sleeper = sleeper
        self._rng = rng
        self._ids = ids
        self._on_attempt = on_attempt
        self.lost_callbacks = 0

    # ------------------------------------------------------------------
    async def _post(self, client: httpx.AsyncClient, payload: dict, timeout: float,
                    plan: str) -> Classification:
        try:
            resp = await asyncio.wait_for(client.post("/quote", json=payload), timeout)
        except (asyncio.TimeoutError, httpx.TimeoutException) as exc:
            e = exc
            e.failure_kind = "timeout"  # type: ignore[attr-defined]
            return classify(None, None, e, plan)
        except httpx.HTTPError as exc:
            exc.failure_kind = "network"  # type: ignore[attr-defined]
            return classify(None, None, exc, plan)
        except asyncio.CancelledError:
            raise
        except Exception as exc:  # noqa: BLE001  - falha interna do cliente: transitoria
            exc.failure_kind = "internal"  # type: ignore[attr-defined]
            return classify(None, None, exc, plan)
        return classify(resp.status_code, resp.content, None, plan)

    def _notify(self, rec: AttemptRecord, override: Optional[OnAttempt]) -> None:
        cb = override or self._on_attempt
        if cb is None:
            return
        try:
            cb(rec)
        except Exception:  # noqa: BLE001
            self.lost_callbacks += 1

    async def quote(self, req: QuoteRequest, on_attempt: Optional[OnAttempt] = None) -> QuoteResult:
        """Nunca levanta erro de rede. Levanta RequestValidationError antes de chamar a rede."""
        req = validate_request(req, self._clock.now().date())
        s = self._s
        quote_id = self._ids.new_quote_id()
        t_start = self._clock.monotonic()
        deadline = t_start + s.quote_total_budget_s
        payload = {k: v for k, v in {
            "plano_id": req.plano_id, "idade": req.idade, "veiculo_ano": req.veiculo_ano,
            "cep": req.cep, "data_inicio": req.data_inicio}.items() if v is not None}
        attempts: list[AttemptRecord] = []
        malformed = 0

        def total_ms() -> int:
            return int((self._clock.monotonic() - t_start) * 1000)

        async with httpx.AsyncClient(base_url=s.quote_base_url, transport=self._transport,
                                     follow_redirects=False) as client:
            for n in range(1, s.quote_max_attempts + 1):
                remaining = deadline - self._clock.monotonic()
                if remaining < MIN_REMAINING_S:
                    break
                timeout = min(s.quote_timeout_s, remaining)
                t0 = self._clock.monotonic()
                try:
                    c = await self._post(client, payload, timeout, req.plano_id)
                except asyncio.CancelledError:
                    rec = AttemptRecord(quote_id, n, None, "cancelled",
                                        int((self._clock.monotonic() - t0) * 1000), "cancelled")
                    attempts.append(rec)
                    self._notify(rec, on_attempt)
                    raise
                latency = int((self._clock.monotonic() - t0) * 1000)

                if c.kind in ("ok", "refused", "client_error"):
                    rec = AttemptRecord(quote_id, n, c.http_status, c.failure_kind, latency,
                                        c.kind)
                    attempts.append(rec)
                    self._notify(rec, on_attempt)
                    kind = {"ok": QuoteKind.OK, "refused": QuoteKind.REFUSED,
                            "client_error": QuoteKind.CLIENT_ERROR}[c.kind]
                    return QuoteResult(kind, quote_id, c.response, c.refusal_reason,
                                       tuple(attempts), total_ms())

                # transitoria
                if c.failure_kind == "malformed_200":
                    malformed += 1
                wait_s: Optional[float] = None
                if n < s.quote_max_attempts:
                    nominal = s.quote_backoff_base_s * 2 ** (n - 1)
                    w = nominal / 2 + self._rng.uniform(0, nominal / 2)
                    if self._clock.monotonic() + w + MIN_REMAINING_S <= deadline:
                        wait_s = w
                rec = AttemptRecord(quote_id, n, c.http_status, c.failure_kind, latency,
                                    "retry" if wait_s is not None else "give_up",
                                    int(wait_s * 1000) if wait_s is not None else None)
                attempts.append(rec)
                self._notify(rec, on_attempt)
                if wait_s is None:
                    break
                await self._sleeper.sleep(wait_s)

        kind = QuoteKind.MALFORMED if malformed >= 2 else QuoteKind.UNAVAILABLE
        return QuoteResult(kind, quote_id, None, None, tuple(attempts), total_ms())
