"""Validacao da requisicao antes de enviar (RFC 0002 4.2, ADR 0013)."""
from __future__ import annotations

import re
from dataclasses import replace
from datetime import date, timedelta

from ..contracts import QuoteRequest, RequestValidationError

PLANOS = ("essencial", "completo", "premium")
_CEP = re.compile(r"^(\d{5})-?(\d{3})$")
_DATA = re.compile(r"^\d{4}-\d{2}-\d{2}$")
FAR_DAYS = 365


def validate_request(req: QuoteRequest, today: date) -> QuoteRequest:
    """Devolve a requisicao normalizada ou levanta RequestValidationError.

    Nao valida elegibilidade (idade > 75, veiculo antigo): regra do legado (RF-11).
    """
    plano = (req.plano_id or "").strip().lower()
    if plano not in PLANOS:
        raise RequestValidationError("plano_id", "invalid")
    if not isinstance(req.idade, int) or isinstance(req.idade, bool) or not 0 <= req.idade <= 200:
        raise RequestValidationError("idade", "out_of_range")
    if (not isinstance(req.veiculo_ano, int) or isinstance(req.veiculo_ano, bool)
            or not 1950 <= req.veiculo_ano <= 2100):
        raise RequestValidationError("veiculo_ano", "out_of_range")
    cep = req.cep
    if cep is not None:
        m = _CEP.match(cep.strip())
        if not m:
            raise RequestValidationError("cep", "invalid_format")
        cep = f"{m.group(1)}-{m.group(2)}"
    data = req.data_inicio
    if data is not None:
        if not _DATA.match(data):
            raise RequestValidationError("data_inicio", "invalid_format")
        try:
            d = date.fromisoformat(data)
        except ValueError as exc:
            raise RequestValidationError("data_inicio", "invalid_date") from exc
        if d < today:
            raise RequestValidationError("data_inicio", "past")
        if d > today + timedelta(days=FAR_DAYS):
            raise RequestValidationError("data_inicio", "confirm_far_date")
    return replace(req, plano_id=plano, cep=cep, data_inicio=data)
