"""Escada de planos por base_mensal crescente (RFC 0003 4.4)."""
from __future__ import annotations

from typing import Optional

PLAN_LADDER = ("essencial", "completo", "premium")


def alternative_plan(current: Optional[str], objection_kind: Optional[str]) -> Optional[str]:
    """Preco: degrau abaixo. Franquia alta: degrau acima (menor franquia). Sem degrau: None."""
    if current not in PLAN_LADDER:
        return None
    i = PLAN_LADDER.index(current)
    j = i + 1 if objection_kind == "franquia" else i - 1
    return PLAN_LADDER[j] if 0 <= j < len(PLAN_LADDER) else None
