"""Lexico determinístico dos sinais de intencao (RFC 0003 4.4, ADR 0016)."""
from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass
from typing import Optional

from ..contracts import Signals


def normalize(text: str) -> str:
    t = unicodedata.normalize("NFKD", text.lower())
    t = "".join(c for c in t if not unicodedata.combining(c))
    t = re.sub(r"[^a-z0-9\s]", " ", t)
    return re.sub(r"\s+", " ", t).strip()


@dataclass(frozen=True, slots=True)
class SignalHint:
    pending_offer: bool = False
    pending_confirmation: bool = False


_HUMAN_VERB = (r"(?:falar|conversar|chamar|passa\w*|transfer\w*|prefiro|quero|preciso|"
               r"posso|pode|gostaria)")
_HUMAN_NOUN = r"(?:atendente|humano|pessoa|vendedor\w*|consultor\w*|corretor\w*)"
RE_HUMAN = [
    re.compile(rf"\b{_HUMAN_VERB}\b.{{0,30}}\b{_HUMAN_NOUN}\b"),
    re.compile(r"\b(?:atendente|humano)\b"),
    re.compile(r"\b(?:falar|conversar)\b.{0,15}\balguem\b"),
]
RE_CLAIM = re.compile(
    r"\b(?:sinistro|acidente|bati|batida|colidi|roubaram|furtaram|fui roubad\w+|"
    r"fui furtad\w+|reclama\w*|cobranca indevida|procon|processar|indeniza\w*)\b")
RE_BUY = re.compile(
    r"\b(?:fechado|fechou|pode emitir|emitir|quero contratar|vamos nessa|vamos fechar|"
    r"aceito|manda o boleto|gerar o boleto)\b")
_NEG_TOKENS = {"nao", "nunca", "sem", "jamais"}
RE_DISCOUNT = re.compile(
    r"\b(?:desconto|abater|abatimento|fazer por|baixar o preco|baixar a franquia|"
    r"ajustar a franquia|ajusta a franquia|parcel\w*)\b")
RE_FRANQUIA_ALTA = re.compile(r"\bfranquia (?:esta |ta |e |muito )?alta\b")
RE_PRICE_OBJ = re.compile(
    r"\b(?:caro|salgad\w+|mais barato|concorrente|ofereceu menos)\b")
RE_PLAN_BARATO = re.compile(r"\bo (?:plano )?mais barato\b")
RE_FOUND_CHEAPER = re.compile(r"\b(?:vi|achei|encontrei|ofereceu|tem)\b.{0,15}mais barato")
RE_HESITATION = re.compile(r"\b(?:preciso pensar|vou pensar|vou ver com|depois eu vejo)\b")
RE_AFFIRM = re.compile(r"(?:^|\b)(?:sim|pode ser|quero|ok|isso|isso mesmo|claro|pode|aceito)\b")
RE_NEG = re.compile(r"^(?:nao|errado)\b|\bnao e\b|\bnao eh\b|\bnao era\b")
RE_ASKS = re.compile(
    r"\b(?:franquia|cobre|cobertura|coberturas|carencia|pro rata|prorata|primeiro pagamento|"
    r"vidros|terceiros|carro reserva)\b")
RE_PLAN = re.compile(r"\b(essencial|completo|premium)\b")


def _buy(t: str, hint: SignalHint) -> bool:
    for m in RE_BUY.finditer(t):
        if m.group(0) == "aceito" and hint.pending_offer:
            continue  # aceite de plano alternativo, nao de contratacao
        before = t[: m.start()].split()[-3:]
        if any(w in _NEG_TOKENS for w in before):
            continue
        return True
    return False


def detect_signals(text: str, hint: SignalHint = SignalHint()) -> Signals:
    t = normalize(text)
    if not t:
        return Signals()
    wants_human = any(r.search(t) for r in RE_HUMAN)
    claim = bool(RE_CLAIM.search(t))
    discount = bool(RE_DISCOUNT.search(t))
    franquia_alta = bool(RE_FRANQUIA_ALTA.search(t))
    barato_plan = bool(RE_PLAN_BARATO.search(t)) and not RE_FOUND_CHEAPER.search(t)
    price_obj = franquia_alta or bool(
        RE_PRICE_OBJ.search(RE_PLAN_BARATO.sub(" ", t) if barato_plan else t))
    kind = "franquia" if franquia_alta else ("preco" if price_obj else None)
    pm = RE_PLAN.search(t)
    plan = pm.group(1) if pm else ("essencial" if barato_plan else None)
    pending = hint.pending_offer or hint.pending_confirmation
    return Signals(
        wants_human=wants_human,
        claim_or_complaint=claim,
        wants_to_buy=_buy(t, hint),
        discount_request=discount,
        price_objection=price_obj,
        objection_kind=kind,
        hesitation=bool(RE_HESITATION.search(t)),
        affirmative=bool(pending and RE_AFFIRM.search(t) and not RE_NEG.search(t)),
        negative=bool(pending and RE_NEG.search(t)),
        asks_about_quote=bool(RE_ASKS.search(t)),
        plan_requested=plan,
    )


_COVERAGE_WORDS = {
    "roubo": "roubo", "furto": "furto", "colisao": "colisao", "terceiros": "terceiros",
    "vidros": "vidros", "vidro": "vidros", "carro reserva": "carro_reserva",
    "assistencia": "assistencia_24h",
}


def question_topics(text: str) -> tuple[str, ...]:
    """Topicos perguntados sobre a cotacao: franquia, carencia, prorata, coberturas, cob:<id>."""
    t = normalize(text)
    out: list[str] = []
    if re.search(r"\bfranquia\b", t):
        out.append("franquia")
    if re.search(r"\bcarencia\b", t):
        out.append("carencia")
    if re.search(r"\b(?:pro rata|prorata|primeiro pagamento)\b", t):
        out.append("prorata")
    for w, cid in _COVERAGE_WORDS.items():
        if re.search(rf"\b{w}\b", t):
            out.append(f"cob:{cid}")
    if re.search(r"\b(?:cobre|cobertura|coberturas)\b", t) and not any(
            o.startswith("cob:") for o in out):
        out.append("coberturas")
    return tuple(dict.fromkeys(out))


def plan_from_text(text: str) -> Optional[str]:
    m = RE_PLAN.search(normalize(text))
    return m.group(1) if m else None
