"""Funcao de decisao pura (RFC 0003 4.4, ADR 0001, 0015 a 0019)."""
from __future__ import annotations

from typing import Any, Mapping, Optional

from ..contracts import (
    OPTIONAL_FIELDS,
    REQUIRED_FIELDS,
    Action,
    Decision,
    DecisionContext,
    Event,
    HandoffReason,
    IdleTimeout,
    InternalFailure,
    LeadMessage,
    PolicyConfig,
    QuoteKind,
    QuoteOutcome,
    RequestInvalid,
    SlotStatus,
    State,
)
from .ladder import alternative_plan

H = HandoffReason
S = State
_NO_HUMAN_CHAT = {S.HANDOFF, S.ENCERRADA_INATIVIDADE}


def _d(action: Action, nxt: State, rule: str, reason: Optional[HandoffReason] = None,
       **params: Any) -> Decision:
    return Decision(action, nxt, rule, reason, params)


def _handoff(rule: str, reason: HandoffReason) -> Decision:
    return _d(Action.HANDOFF, S.HANDOFF, rule, reason)


def _status(ctx: DecisionContext, name: str) -> SlotStatus:
    s = ctx.slots.get(name)
    return s.status if s is not None else SlotStatus.MISSING


def _chosen_plan(ctx: DecisionContext) -> str:
    s = ctx.slots.get("plano_id")
    if s is not None and s.status is SlotStatus.CERTAIN and s.value:
        return str(s.value)
    return "completo"


def _lead_message(ctx: DecisionContext, ev: LeadMessage, cfg: PolicyConfig) -> Decision:
    st, sig = ctx.state, ev.signals
    if st in _NO_HUMAN_CHAT:
        return _d(Action.NOOP, st, "P14")
    if sig.claim_or_complaint:
        return _handoff("P01", H.SINISTRO_RECLAMACAO)
    if sig.wants_human:
        return _handoff("P02", H.PEDIDO_HUMANO)
    if st is S.ENCERRADA_RECUSA:
        if ctx.refusal_reminders < 1:
            return _d(Action.REFUSAL_REMINDER, st, "P12")
        return _d(Action.NOOP, st, "P13")
    if st is S.COTANDO:
        return _d(Action.NOOP, st, "P14")

    if st is S.COTACAO_APRESENTADA:
        if sig.wants_to_buy and not sig.negative:
            return _handoff("P03", H.INTENCAO_CONTRATAR)
        if sig.discount_request:
            return _handoff("P04", H.OBJECAO_FORA_DE_ALCANCE)
        if sig.price_objection and ctx.objections + 1 >= cfg.objection_limit:
            return _handoff("P05", H.OBJECAO_FORA_DE_ALCANCE)
        if sig.price_objection:
            offer = alternative_plan(ctx.current_plan, sig.objection_kind)
            return _d(Action.REPRESENT_OFFER, st, "P06", objection=True, offer=offer)
        if ctx.pending_offer and sig.affirmative:
            return _d(Action.QUOTE, S.COTANDO, "P07", plan=ctx.pending_offer)
        if sig.plan_requested and sig.plan_requested != ctx.current_plan:
            return _d(Action.QUOTE, S.COTANDO, "P08", plan=sig.plan_requested)
        if sig.asks_about_quote:
            return _d(Action.ANSWER_FROM_QUOTE, st, "P09")
        if sig.hesitation:
            return _d(Action.ACK_HESITATION, st, "P10")
        return _d(Action.ANSWER_FROM_QUOTE, st, "P11", generic=True)

    # Novo / Qualificando
    limit = 1 + cfg.reask_limit
    missing = [f for f in REQUIRED_FIELDS if _status(ctx, f) is SlotStatus.MISSING]
    ambiguous = [f for f in REQUIRED_FIELDS if _status(ctx, f) is SlotStatus.AMBIGUOUS]
    if any(ctx.asks.get(f, 0) >= limit for f in missing + ambiguous):
        return _handoff("P15", H.DADOS_INSUFICIENTES)
    if ambiguous:
        f = ambiguous[0]
        slot = ctx.slots[f]
        cand = slot.candidates[0] if slot.candidates else slot.value
        return _d(Action.ASK_CONFIRM, S.QUALIFICANDO, "P16", field=f, candidate=cand, asks=(f,))
    if missing:
        opt = [o for o in OPTIONAL_FIELDS
               if _status(ctx, o) is SlotStatus.MISSING and ctx.asks.get(o, 0) == 0]
        asks = tuple(missing) + tuple(opt)
        if ev.media:
            return _d(Action.MEDIA_ACK, S.QUALIFICANDO, "P17", fields=tuple(missing),
                      asks=tuple(missing))
        action = Action.GREET_AND_ASK if st is S.NOVO else Action.ASK_FIELD
        return _d(action, S.QUALIFICANDO, "P18", fields=asks, asks=asks)
    return _d(Action.QUOTE, S.COTANDO, "P19", plan=_chosen_plan(ctx))


def _quote_outcome(ctx: DecisionContext, ev: QuoteOutcome) -> Decision:
    if ctx.state in _NO_HUMAN_CHAT or ctx.state is S.ENCERRADA_RECUSA:
        return _d(Action.NOOP, ctx.state, "P14")
    if ctx.state is not S.COTANDO:
        return _handoff("X01", H.ERRO_INTERNO)
    k = ev.kind
    if k is QuoteKind.OK:
        return _d(Action.PRESENT, S.COTACAO_APRESENTADA, "Q01")
    if k is QuoteKind.REFUSED:
        return _d(Action.REFUSAL_CLOSE, S.ENCERRADA_RECUSA, "Q02")
    if k is QuoteKind.UNAVAILABLE:
        return _handoff("Q03", H.QUOTE_INDISPONIVEL)
    return _handoff("Q04", H.ERRO_INTERNO)


def _request_invalid(ctx: DecisionContext, ev: RequestInvalid, cfg: PolicyConfig) -> Decision:
    if ctx.state in _NO_HUMAN_CHAT or ctx.state is S.ENCERRADA_RECUSA:
        return _d(Action.NOOP, ctx.state, "P14")
    if ctx.state not in (S.COTANDO, S.QUALIFICANDO, S.NOVO):
        return _handoff("X01", H.ERRO_INTERNO)
    f = ev.field
    asked = ctx.asks.get(f, 0)
    if f in OPTIONAL_FIELDS:
        if ev.code == "confirm_far_date":
            slot = ctx.slots.get(f)
            cand = slot.value if slot is not None else None
            return _d(Action.ASK_CONFIRM, S.QUALIFICANDO, "Q05", field=f, candidate=cand,
                      asks=(f,))
        if asked >= 1:
            return _d(Action.QUOTE, S.COTANDO, "Q05", plan=ctx.quoting_plan or _chosen_plan(ctx),
                      drop=(f,), reset=f)
        return _d(Action.ASK_FIELD, S.QUALIFICANDO, "Q05", fields=(f,), asks=(f,), reset=f)
    if f in REQUIRED_FIELDS:
        if asked >= 1 + cfg.reask_limit:
            return _handoff("P15", H.DADOS_INSUFICIENTES)
        return _d(Action.ASK_FIELD, S.QUALIFICANDO, "Q05", fields=(f,), asks=(f,), reset=f)
    return _handoff("Q04", H.ERRO_INTERNO)  # plano_id invalido: erro nosso


def decide(ctx: DecisionContext, event: Event, cfg: PolicyConfig = PolicyConfig()) -> Decision:
    """Funcao pura: sem E/S, relogio ou aleatoriedade."""
    if isinstance(event, LeadMessage):
        return _lead_message(ctx, event, cfg)
    if isinstance(event, QuoteOutcome):
        return _quote_outcome(ctx, event)
    if isinstance(event, RequestInvalid):
        return _request_invalid(ctx, event, cfg)
    if isinstance(event, IdleTimeout):
        if ctx.state in (S.QUALIFICANDO, S.COTACAO_APRESENTADA):
            return _d(Action.IDLE_CLOSE, S.ENCERRADA_INATIVIDADE, "I01")
        return _d(Action.NOOP, ctx.state, "I02")
    if isinstance(event, InternalFailure):
        if ctx.state in _NO_HUMAN_CHAT or ctx.state is S.ENCERRADA_RECUSA:
            return _d(Action.NOOP, ctx.state, "I02")
        return _handoff("X01", H.ERRO_INTERNO)
    return _handoff("X01", H.ERRO_INTERNO)
