"""Extrator: regex primeiro, LLM depois, fallback regex, confirmacao (RFC 0004, ADR 0020, 0023)."""
from __future__ import annotations

import time
from dataclasses import dataclass, field
from typing import Mapping, Optional

from ..contracts import Clock, Extraction, MessageType, Slot, SlotStatus
from ..llm.ports import LlmExtractor
from ..privacy import MaskedViews
from . import regex_pass
from .merge import merge, needs_llm

CERTAIN, AMBIGUOUS, MISSING = SlotStatus.CERTAIN, SlotStatus.AMBIGUOUS, SlotStatus.MISSING


@dataclass(frozen=True, slots=True)
class AskContext:
    last_asked: tuple[str, ...] = ()
    pending_confirmation: Mapping[str, object] = field(default_factory=dict)
    last_question: Optional[str] = None


class Extractor:
    def __init__(self, clock: Clock, llm: Optional[LlmExtractor] = None):
        self._clock = clock
        self._llm = llm

    async def extract(self, views: MaskedViews, mtype: MessageType, ctx: AskContext = AskContext(),
                      affirmative: bool = False, negative: bool = False) -> Extraction:
        if mtype is not MessageType.TEXT:
            return Extraction()  # midia: marcador nao e dado do lead (ADR 0023)
        today = self._clock.now().date()
        text = views.extraction_text
        slots = dict(regex_pass.run(text, today, ctx.last_asked))

        llm_used, llm_error, llm_ms = False, None, None
        if self._llm is not None and text.strip() and needs_llm(slots, text):
            llm_used = True
            t0 = time.monotonic()
            try:
                res = await self._llm.extract(text, ctx.last_question)
            except Exception as exc:  # noqa: BLE001
                res, llm_error = None, type(exc).__name__
            llm_ms = int((time.monotonic() - t0) * 1000)
            if res is None and llm_error is None:
                llm_error = "llm_unavailable"
            slots = merge(slots, res, text, today.year)

        # confirmacao de valor ambiguo (RF-06)
        cleared: list[str] = []
        for fname, cand in ctx.pending_confirmation.items():
            new = slots.get(fname)
            has_new = new is not None and new.status is not MISSING
            if affirmative and not has_new:
                slots[fname] = Slot(cand, CERTAIN, (), "confirmation")  # type: ignore[arg-type]
            elif negative and not has_new:
                cleared.append(fname)
        return Extraction(
            idade=slots["idade"], veiculo_ano=slots["veiculo_ano"], cep=slots["cep"],
            data_inicio=slots["data_inicio"], plano_id=slots["plano_id"], llm_used=llm_used,
            llm_error=llm_error, llm_latency_ms=llm_ms, cleared=tuple(cleared))
