import unicodedata
from datetime import date, timedelta
from typing import Mapping, Sequence

from ..contracts import Slot, SlotStatus

CERTAIN, AMBIGUOUS, MISSING = SlotStatus.CERTAIN, SlotStatus.AMBIGUOUS, SlotStatus.MISSING
_CEP = re.compile(r"\b(\d{5})-?(\d{3})\b")
_ISO = re.compile(r"\b(\d{4})-(\d{2})-(\d{2})\b")
_DMY = re.compile(r"\b(\d{1,2})/(\d{1,2})/(\d{4})\b")
_DM = re.compile(r"\b(\d{1,2})/(\d{1,2})\b")
_HOJE = re.compile(r"\bhoje\b")
_AMANHA = re.compile(r"\bamanha\b")
_DIA = re.compile(r"\bdia (\d{1,2})\b")
_IDADE = [re.compile(r"\b(?:tenho )?(\d{1,3}) anos?\b"), re.compile(r"\bidade:? ?(\d{1,3})\b")]
_YEAR = re.compile(r"\b(19[5-9]\d|20\d{2})\b")
_YEAR_AFTER_ANO = re.compile(r"\bano (?:de |do |:)?\s*(19[5-9]\d|20\d{2})\b")
_PLAN = re.compile(r"\b(essencial|completo|premium)\b")
_CHEAPEST = re.compile(r"\bo (?:plano )?mais barato\b")


def fold(text: str) -> str:
    t = unicodedata.normalize("NFKD", text.lower())
    return "".join(c for c in t if not unicodedata.combining(c))


def _blank(text: str, spans: Sequence[tuple[int, int]]) -> str:
    chars = list(text)
    for a, b in spans:
        for i in range(a, b):
            chars[i] = " "
    return "".join(chars)


def _cep(t: str):
    found = [(m.group(1) + "-" + m.group(2), m.span()) for m in _CEP.finditer(t)]
    vals = list(dict.fromkeys(v for v, _ in found))
    slot = Slot() if not vals else (
        Slot(vals[0], CERTAIN) if len(vals) == 1 else Slot(None, AMBIGUOUS, tuple(vals)))
    return slot, _blank(t, [s for _, s in found])


def _mkdate(y: int, m: int, d: int):
    try:
        return date(y, m, d)
    except ValueError:
        return None


def _date(t: str, today: date):
    spans: list[tuple[int, int]] = []
    cand: list[date | None] = []
    for m in _ISO.finditer(t):
        cand.append(_mkdate(int(m.group(1)), int(m.group(2)), int(m.group(3))))
        spans.append(m.span())
    t2 = _blank(t, spans)
    spans2: list[tuple[int, int]] = []
    for m in _DMY.finditer(t2):
        cand.append(_mkdate(int(m.group(3)), int(m.group(2)), int(m.group(1))))
        spans2.append(m.span())
    t3 = _blank(t2, spans2)
    spans3: list[tuple[int, int]] = []
    for m in _DM.finditer(t3):
        d = _mkdate(today.year, int(m.group(2)), int(m.group(1)))
        if d is not None and d < today:
            d = _mkdate(today.year + 1, int(m.group(2)), int(m.group(1)))
        cand.append(d)
        spans3.append(m.span())
    t4 = _blank(t3, spans3)
    spans4: list[tuple[int, int]] = []
    for rx, delta in ((_HOJE, 0), (_AMANHA, 1)):
        for m in rx.finditer(t4):
            cand.append(today + timedelta(days=delta))
            spans4.append(m.span())
    for m in _DIA.finditer(t4):
        dd = int(m.group(1))
        d = _mkdate(today.year, today.month, dd)
        if d is None or d < today:
            ny, nm = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
            d = _mkdate(ny, nm, dd)
        cand.append(d)
        spans4.append(m.span())
    valid = [d for d in cand if d is not None and d >= today]
    allspans = spans + spans2 + spans3 + spans4
    rest = _blank(t, allspans)
    if not valid:
        return Slot(), rest
    uniq = list(dict.fromkeys(d.isoformat() for d in valid))
    slot = Slot(uniq[0], CERTAIN) if len(uniq) == 1 else Slot(None, AMBIGUOUS, tuple(uniq))
    return slot, rest


def _idade(t: str, ask_idade: bool):
    found: list[tuple[int, tuple[int, int]]] = []
    for rx in _IDADE:
        for m in rx.finditer(t):
            s, e = m.span()
            if any(s < b and a < e for _, (a, b) in found):
                continue
            window = t[max(0, s - 15):s]
            if "carro" in window or "veiculo" in window:
                continue  # idade do carro nao e idade do lead
            found.append((int(m.group(1)), (s, e)))
    if not found and ask_idade:
        m = re.fullmatch(r"\s*(\d{1,3})\s*", t)
        if m:
            found.append((int(m.group(1)), m.span()))
    rest = _blank(t, [sp for _, sp in found])
    vals = list(dict.fromkeys(v for v, _ in sorted(found, key=lambda x: x[1][0])))
    if not vals:
        return Slot(), rest
    if len(vals) > 1:
        return Slot(None, AMBIGUOUS, tuple(vals)), rest
    v = vals[0]
    if 18 <= v <= 99:
        return Slot(v, CERTAIN), rest
    if 0 <= v <= 120:
        return Slot(v, AMBIGUOUS, (v,)), rest
    return Slot(), rest


def _ano(t: str, current_year: int):
    pref = list(dict.fromkeys(int(m.group(1)) for m in _YEAR_AFTER_ANO.finditer(t)))
    alls = list(dict.fromkeys(int(m.group(1)) for m in _YEAR.finditer(t)))
    vals = pref if pref else alls
    if not vals:
        return Slot()
    if len(vals) > 1:
        return Slot(None, AMBIGUOUS, tuple(vals))
    v = vals[0]
    if 1950 <= v <= current_year + 1:
        return Slot(v, CERTAIN)
    return Slot(v, AMBIGUOUS, (v,))


def _plano(t: str):
    vals = list(dict.fromkeys(m.group(1) for m in _PLAN.finditer(t)))
    if not vals and _CHEAPEST.search(t):
        vals = ["essencial"]
    if not vals:
        return Slot()
    if len(vals) > 1:
        return Slot(None, AMBIGUOUS, tuple(vals))
    return Slot(vals[0], CERTAIN)


def run(text: str, today: date, last_asked: Sequence[str] = ()) -> Mapping[str, Slot]:
    t = fold(text)
    cep, t = _cep(t)
    data, t = _date(t, today)
    idade, t = _idade(t, "idade" in last_asked)
    ano = _ano(t, today.year) if (_YEAR.search(t)) else Slot()
    plano = _plano(fold(text))
    return {"idade": idade, "veiculo_ano": ano, "cep": cep, "data_inicio": data,
            "plano_id": plano}
