"""Mescla regex e LLM (RFC 0004 4.4)."""
from __future__ import annotations

import re
from typing import Mapping, Optional

from ..contracts import Slot, SlotStatus
from ..llm.ports import LlmExtraction

CERTAIN, AMBIGUOUS, MISSING = SlotStatus.CERTAIN, SlotStatus.AMBIGUOUS, SlotStatus.MISSING
_PLANS = ("essencial", "completo", "premium")


def _tokens(text: str) -> set[str]:
    return set(re.findall(r"\d+", text))


def _plausible(field: str, v, year: int) -> bool:
    if v is None:
        return False
    if field == "idade":
        return isinstance(v, int) and not isinstance(v, bool) and 18 <= v <= 99
    if field == "veiculo_ano":
        return isinstance(v, int) and not isinstance(v, bool) and 1950 <= v <= year + 1
    if field == "cep":
        return isinstance(v, str) and re.fullmatch(r"\d{5}-?\d{3}", v) is not None
    if field == "data_inicio":
        return isinstance(v, str) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", v) is not None
    if field == "plano_id":
        return v in _PLANS
    return False


def _in_text(field: str, v, text: str) -> bool:
    """O valor do LLM precisa existir como token numerico no texto enviado."""
    if field == "plano_id":
        return str(v) in text.lower()
    toks = _tokens(text)
    if field in ("idade", "veiculo_ano"):
        return str(v) in toks
    if field == "cep":
        return re.sub(r"\D", "", str(v)) in {re.sub(r"\D", "", m) for m in
                                              re.findall(r"\d{5}-?\d{3}", text)}
    if field == "data_inicio":
        y, m, d = str(v).split("-")
        return {y, str(int(m)), str(int(d))} <= toks | {str(int(t)) for t in toks if t.isdigit()}
    return False


def needs_llm(slots: Mapping[str, Slot], text: str) -> bool:
    if any(slots[f].status is not CERTAIN for f in ("idade", "veiculo_ano")):
        return True
    if any(s.status is AMBIGUOUS for s in slots.values()):
        return True
    return False


def merge(slots: Mapping[str, Slot], llm: Optional[LlmExtraction], text: str, year: int
          ) -> dict[str, Slot]:
    out = dict(slots)
    if llm is None:
        return out
    for field in ("idade", "veiculo_ano", "cep", "data_inicio", "plano_id"):
        v = getattr(llm, field)
        reg = slots[field]
        ok = _plausible(field, v, year) and _in_text(field, v, text)
        if not ok:
            continue
        if reg.status is CERTAIN:
            if reg.value != v and str(reg.value) != str(v):
                out[field] = Slot(None, AMBIGUOUS, (reg.value, v), "regex+llm")
            continue
        if reg.status is MISSING:
            out[field] = Slot(v, CERTAIN, (), "llm")
        elif reg.status is AMBIGUOUS and v in reg.candidates:
            continue
    return out
