"""Guarda final de numeros: todo token numerico do texto precisa ter sido injetado (RFC 0004 4.8)."""
from __future__ import annotations

import re
from typing import Iterable

_NUM = re.compile(r"\d[\d.,]*")


def tokens(text: str) -> set[str]:
    return {t.rstrip(".,") for t in _NUM.findall(text)}


def numbers_ok(text: str, allowed: Iterable[str]) -> bool:
    return tokens(text) <= set(allowed)
