class Presenter:
    def __init__(self, frames_default: dict[K, Frame] | None = None) -> None:
        self._defaults = frames_default or DEFAULT_FRAMES

    def default_frame(self, kind: K) -> Frame:
        return self._defaults.get(kind, Frame())

    # ------------------------------------------------------------------ API
    def kind_for(self, action: Action) -> Optional[K]:
        return {
            Action.GREET_AND_ASK: K.GREETING, Action.ASK_FIELD: K.ASK_FIELD,
            Action.ASK_CONFIRM: K.ASK_CONFIRMATION, Action.MEDIA_ACK: K.MEDIA_ACK,
            Action.PRESENT: K.QUOTE_PRESENTED, Action.REPRESENT_OFFER: K.ANSWER_FROM_QUOTE,
            Action.ANSWER_FROM_QUOTE: K.ANSWER_FROM_QUOTE,
            Action.ACK_HESITATION: K.ANSWER_FROM_QUOTE, Action.REFUSAL_CLOSE: K.QUOTE_REFUSED,
            Action.REFUSAL_REMINDER: K.QUOTE_REFUSED, Action.HANDOFF: K.HANDOFF,
            Action.IDLE_CLOSE: K.IDLE_CLOSE,
        }.get(action)

    def render(self, decision: Decision, view: PresentationView,
               frame: Optional[Frame] = None) -> Optional[Rendered]:
