        try:
            body = self._body(decision, view, kind)
        except _MissingData:
            return Rendered(FALLBACK, kind, None, "price_guard")
        for fr in ([frame] if frame else []) + [self.default_frame(kind)]:
            text = self._compose(fr, body)
            if self._valid(text, body, view):
                return Rendered(text, kind, view.quote_id if "R$" in text else None,
                                "frame_guard" if (frame is not None and fr is not frame) else None)
        return Rendered(FALLBACK, kind, None, "price_guard")

    def render_unavailable(self) -> Rendered:
        return Rendered("Não consegui concluir sua cotação agora.", K.QUOTE_UNAVAILABLE)

    def render_progress(self) -> Rendered:
        return Rendered("Estou consultando a cotação, só um instante.", K.PROGRESS)

    # ------------------------------------------------------------- internos
    @staticmethod
    def _compose(frame: Frame, body: _Builder) -> str:
        parts = ([frame.opening] if frame.opening else []) + body.lines + (
            [frame.closing] if frame.closing else [])
