    @staticmethod
    def _valid(text: str, body: _Builder, view: PresentationView) -> bool:
        if not tokens(text) <= body.allowed:
            return False
        return not ("R$" in text and view.quote_id is None)

    def _body(self, d: Decision, v: PresentationView, kind: K) -> _Builder:
        b = _Builder()
        a = d.action
        if a in (Action.GREET_AND_ASK, Action.ASK_FIELD, Action.MEDIA_ACK):
            fields = v.fields or tuple(d.params.get("fields", ()))
            lista = _join([CAMPO_PEDIDO[f] for f in fields if f in CAMPO_PEDIDO])
            if a is Action.GREET_AND_ASK:
