            b.lit("Se quiser falar com uma pessoa, é só pedir.")
        elif a is Action.HANDOFF:
            b.lit(HANDOFF_TEXT[v.handoff_reason or d.handoff_reason or HandoffReason.ERRO_INTERNO])
        elif a is Action.IDLE_CLOSE:
            b.lit("Vou encerrar por aqui por enquanto. Quando quiser retomar a cotação, é só me "
                  "chamar.")
        return b

    @staticmethod
    def _need(v: PresentationView) -> QuoteResponse:
        if v.last_quote is None:
            raise _MissingData()
        return v.last_quote

    def _present(self, b: _Builder, v: PresentationView) -> None:
        q = self._need(v)
        b.val("Plano {}: {} por mês, com franquia de {}.", q.plano_nome, format_brl(q.premio_mensal),
              format_brl(q.franquia))
        b.lit("Coberturas: " + _join([_label(c) for c in q.coberturas]) + ".")
        if q.carencia.coberturas:
            b.val(_join([_label(c) for c in q.carencia.coberturas]).capitalize()
                  + " só passam a valer {} dias após o início da vigência.", str(q.carencia.dias))
        if q.pro_rata is not None:
            p = q.pro_rata
            b.val("Primeiro pagamento proporcional: {} de {} dias, {}. Os meses seguintes são de {}.",
                  str(p.dias_cobrados), str(p.dias_no_mes), format_brl(p.valor_primeiro_pagamento),
                  format_brl(q.premio_mensal))
        b.lit("Esta é uma cotação, sujeita a confirmação na contratação.")

    def _answer(self, b: _Builder, v: PresentationView) -> None:
        q = self._need(v)
        topics = v.topics
        if not topics:
            if v.generic:
                b.val("Esta é a cotação do plano {}: {} por mês, com franquia de {}.",
                      q.plano_nome, format_brl(q.premio_mensal), format_brl(q.franquia))
                b.lit("Posso explicar coberturas, franquia e carência, ou chamar um colega se "
                      "preferir.")
            else:
                b.lit("Não tenho essa informação nesta cotação. Posso chamar um colega para ajudar.")
            return
        for t in topics:
            if t == "franquia":
                b.val("A franquia do plano {} é {}.", q.plano_nome, format_brl(q.franquia))
            elif t == "carencia":
                if q.carencia.coberturas:
                    b.val(_join([_label(c) for c in q.carencia.coberturas]).capitalize()
                          + " só passam a valer {} dias após o início da vigência.",
                          str(q.carencia.dias))
                else:
                    b.lit("Esta cotação não tem coberturas com carência.")
            elif t == "prorata":
                if q.pro_rata is not None:
                    p = q.pro_rata
                    b.val("Primeiro pagamento proporcional: {} de {} dias, {}. Os meses seguintes "
                          "são de {}.", str(p.dias_cobrados), str(p.dias_no_mes),
                          format_brl(p.valor_primeiro_pagamento), format_brl(q.premio_mensal))
                else:
                    b.lit("Não tenho informação de pro-rata nesta cotação. Posso chamar um colega "
                          "para ajudar.")
            elif t == "coberturas":
                b.val("O plano {} cobre: " + _join([_label(c) for c in q.coberturas]) + ".",
                      q.plano_nome)
            elif t.startswith("cob:"):
                cid = t[4:]
                if cid in q.coberturas:
                    b.val("Sim, o plano {} cobre " + _label(cid) + ".", q.plano_nome)
                    if cid in q.carencia.coberturas:
                        b.val("Lembrando: " + _join([_label(c) for c in q.carencia.coberturas])
                              + " só passam a valer {} dias após o início da vigência.",
                              str(q.carencia.dias))
                else:
                    b.val("O plano {} não inclui " + _label(cid) + " nesta cotação.", q.plano_nome)


class _MissingData(Exception):
