"""Templates em pt-BR e renderizacao das decisoes (RFC 0001 4.4, 4.5; RFC 0003 4.3)."""
from __future__ import annotations

from dataclasses import dataclass
from typing import Optional, Sequence

from ..contracts import (
    Action,
    Decision,
    HandoffReason,
    MessageType,
    OutboundKind as K,
    QuoteResponse,
)
from .frames import DEFAULT_FRAMES, Frame
from .money import format_brl
from .numbers_guard import tokens

COBERTURA = {"colisao": "colisão", "roubo": "roubo", "furto": "furto", "terceiros": "terceiros",
             "vidros": "vidros", "carro_reserva": "carro reserva",
             "assistencia_24h": "assistência 24h"}
CAMPO_PEDIDO = {"idade": "a sua idade", "veiculo_ano": "o ano do veículo",
                "cep": "o CEP de onde o carro dorme (opcional)",
                "data_inicio": "a data em que quer começar a cobertura (opcional)"}
CAMPO_CONFIRMA = {"idade": "a sua idade", "veiculo_ano": "o ano do veículo",
                  "cep": "o CEP", "data_inicio": "a data de início"}
MIDIA = {MessageType.AUDIO: "áudio", MessageType.IMAGE: "imagem",
         MessageType.DOCUMENT: "documento"}
HANDOFF_TEXT = {
    HandoffReason.QUOTE_INDISPONIVEL: "Vou chamar um colega da equipe para te ajudar com a cotação.",
    HandoffReason.PEDIDO_HUMANO: "Claro! Vou passar sua conversa para um colega da equipe.",
    HandoffReason.INTENCAO_CONTRATAR: ("Que bom! Um colega da equipe vai assumir a conversa para "
                                       "concluir a contratação com você."),
    HandoffReason.SINISTRO_RECLAMACAO: ("Entendi. Vou encaminhar você para um colega da equipe "
                                        "que pode te ajudar com isso."),
    HandoffReason.OBJECAO_FORA_DE_ALCANCE: ("Entendo. Para avaliar essa questão de valores, vou "
                                            "chamar um colega da equipe."),
    HandoffReason.DADOS_INSUFICIENTES: ("Para seguir, vou chamar um colega da equipe que pode te "
                                        "ajudar a completar as informações."),
    HandoffReason.ERRO_INTERNO: ("Tive um problema técnico aqui. Vou chamar um colega da equipe "
                                 "para continuar com você."),
}
FALLBACK = "Desculpe, não consegui montar essa resposta agora. Vou chamar um colega da equipe."


def _join(items: Sequence[str]) -> str:
    items = list(items)
    if len(items) <= 1:
        return "".join(items)
    return ", ".join(items[:-1]) + " e " + items[-1]


def _label(cid: str) -> str:
    return COBERTURA.get(cid, cid)


def _fmt_date(value: object) -> str:
    s = str(value)
    if len(s) == 10 and s[4] == "-" and s[7] == "-":
        return f"{s[8:10]}/{s[5:7]}/{s[0:4]}"
    return s


@dataclass(frozen=True, slots=True)
class PresentationView:
    last_quote: Optional[QuoteResponse] = None
    quote_id: Optional[str] = None
    refusal_reason: Optional[str] = None
    fields: tuple[str, ...] = ()
    field: Optional[str] = None
    candidate: object = None
    media_type: Optional[MessageType] = None
    handoff_reason: Optional[HandoffReason] = None
    alt_plan_name: Optional[str] = None
    topics: tuple[str, ...] = ()
    generic: bool = False


@dataclass(frozen=True, slots=True)
class Rendered:
    text: str
    kind: K
    quote_id: Optional[str] = None
    guard_violation: Optional[str] = None


class _Builder:
    """Literais nao tem digitos; valores injetados registram os tokens permitidos."""

    def __init__(self) -> None:
        self.lines: list[str] = []
        self.allowed: set[str] = set()

    def lit(self, s: str) -> "_Builder":
        self.lines.append(s)
        return self

    def val(self, template: str, *values: str) -> "_Builder":
        for v in values:
            self.allowed |= tokens(v)
        self.lines.append(template.format(*values))
        return self


class Presenter:
    def __init__(self, frames_default: dict[K, Frame] | None = None) -> None:
        self._defaults = frames_default or DEFAULT_FRAMES

    def default_frame(self, kind: K) -> Frame:
        return self._defaults.get(kind, Frame())

    # ------------------------------------------------------------------ API
    def kind_for(self, action: Action) -> Optional[K]:
        return {
            Action.GREET_AND_ASK: K.GREETING, Action.ASK_FIELD: K.ASK_FIELD,
            Action.ASK_CONFIRM: K.ASK_CONFIRMATION, Action.MEDIA_ACK: K.MEDIA_ACK,
            Action.PRESENT: K.QUOTE_PRESENTED, Action.REPRESENT_OFFER: K.ANSWER_FROM_QUOTE,
            Action.ANSWER_FROM_QUOTE: K.ANSWER_FROM_QUOTE,
            Action.ACK_HESITATION: K.ANSWER_FROM_QUOTE, Action.REFUSAL_CLOSE: K.QUOTE_REFUSED,
            Action.REFUSAL_REMINDER: K.QUOTE_REFUSED, Action.HANDOFF: K.HANDOFF,
            Action.IDLE_CLOSE: K.IDLE_CLOSE,
        }.get(action)

    def render(self, decision: Decision, view: PresentationView,
               frame: Optional[Frame] = None) -> Optional[Rendered]:
        kind = self.kind_for(decision.action)
        if kind is None:
            return None  # QUOTE e NOOP nao geram texto
        try:
            body = self._body(decision, view, kind)
        except _MissingData:
            return Rendered(FALLBACK, kind, None, "price_guard")
        for fr in ([frame] if frame else []) + [self.default_frame(kind)]:
            text = self._compose(fr, body)
            if self._valid(text, body, view):
                return Rendered(text, kind, view.quote_id if "R$" in text else None,
                                "frame_guard" if (frame is not None and fr is not frame) else None)
        return Rendered(FALLBACK, kind, None, "price_guard")

    def render_unavailable(self) -> Rendered:
        return Rendered("Não consegui concluir sua cotação agora.", K.QUOTE_UNAVAILABLE)

    def render_progress(self) -> Rendered:
        return Rendered("Estou consultando a cotação, só um instante.", K.PROGRESS)

    # ------------------------------------------------------------- internos
    @staticmethod
    def _compose(frame: Frame, body: _Builder) -> str:
        parts = ([frame.opening] if frame.opening else []) + body.lines + (
            [frame.closing] if frame.closing else [])
        return "\n".join(parts)

    @staticmethod
    def _valid(text: str, body: _Builder, view: PresentationView) -> bool:
        if not tokens(text) <= body.allowed:
            return False
        return not ("R$" in text and view.quote_id is None)

    def _body(self, d: Decision, v: PresentationView, kind: K) -> _Builder:
        b = _Builder()
        a = d.action
        if a in (Action.GREET_AND_ASK, Action.ASK_FIELD, Action.MEDIA_ACK):
            fields = v.fields or tuple(d.params.get("fields", ()))
            lista = _join([CAMPO_PEDIDO[f] for f in fields if f in CAMPO_PEDIDO])
            if a is Action.GREET_AND_ASK:
                b.lit("Olá! Sou o assistente virtual da AutoSeguro. Para cotar o seguro do seu "
                      f"carro, preciso que você me informe {lista}.")
            elif a is Action.ASK_FIELD:
                b.lit(f"Para continuar, preciso que você me informe {lista}.")
            else:
                tipo = MIDIA.get(v.media_type, "arquivo")
                b.lit(f"Recebi seu {tipo}, mas não consigo abrir arquivos por aqui. "
                      f"Pode me informar {lista} em texto?")
        elif a is Action.ASK_CONFIRM:
            campo = CAMPO_CONFIRMA.get(v.field or "", "esse dado")
            cand = _fmt_date(v.candidate) if v.field == "data_inicio" else str(v.candidate)
            b.val("Só confirmando: " + campo + " é {}?", cand)
        elif a is Action.PRESENT:
            self._present(b, v)
        elif a is Action.REPRESENT_OFFER:
            q = self._need(v)
            b.val("Entendo. Reforçando: o plano {} custa {} por mês, com franquia de {}.",
                  q.plano_nome, format_brl(q.premio_mensal), format_brl(q.franquia))
            b.lit("Coberturas: " + _join([_label(c) for c in q.coberturas]) + ".")
            if v.alt_plan_name:
                b.val("Se preferir, posso cotar o plano {}. Quer que eu faça isso?", v.alt_plan_name)
            else:
                b.lit("Se quiser falar com uma pessoa sobre valores, é só pedir.")
        elif a is Action.ANSWER_FROM_QUOTE:
            self._answer(b, v)
        elif a is Action.ACK_HESITATION:
            b.lit("Sem problema, fique à vontade para pensar. Se tiver dúvidas sobre a cotação, "
                  "é só perguntar.")
        elif a is Action.REFUSAL_CLOSE:
            b.val("{} Por isso não consigo seguir com essa cotação.", v.refusal_reason or "")
            b.lit("Se quiser falar com uma pessoa, é só pedir.")
        elif a is Action.REFUSAL_REMINDER:
            b.val("Essa cotação foi encerrada. Motivo: {}", v.refusal_reason or "")
            b.lit("Se quiser falar com uma pessoa, é só pedir.")
        elif a is Action.HANDOFF:
            b.lit(HANDOFF_TEXT[v.handoff_reason or d.handoff_reason or HandoffReason.ERRO_INTERNO])
        elif a is Action.IDLE_CLOSE:
            b.lit("Vou encerrar por aqui por enquanto. Quando quiser retomar a cotação, é só me "
                  "chamar.")
        return b

    @staticmethod
    def _need(v: PresentationView) -> QuoteResponse:
        if v.last_quote is None:
            raise _MissingData()
        return v.last_quote

    def _present(self, b: _Builder, v: PresentationView) -> None:
        q = self._need(v)
        b.val("Plano {}: {} por mês, com franquia de {}.", q.plano_nome, format_brl(q.premio_mensal),
              format_brl(q.franquia))
        b.lit("Coberturas: " + _join([_label(c) for c in q.coberturas]) + ".")
        if q.carencia.coberturas:
            b.val(_join([_label(c) for c in q.carencia.coberturas]).capitalize()
                  + " só passam a valer {} dias após o início da vigência.", str(q.carencia.dias))
        if q.pro_rata is not None:
            p = q.pro_rata
            b.val("Primeiro pagamento proporcional: {} de {} dias, {}. Os meses seguintes são de {}.",
                  str(p.dias_cobrados), str(p.dias_no_mes), format_brl(p.valor_primeiro_pagamento),
                  format_brl(q.premio_mensal))
        b.lit("Esta é uma cotação, sujeita a confirmação na contratação.")

    def _answer(self, b: _Builder, v: PresentationView) -> None:
        q = self._need(v)
        topics = v.topics
        if not topics:
            if v.generic:
                b.val("Esta é a cotação do plano {}: {} por mês, com franquia de {}.",
                      q.plano_nome, format_brl(q.premio_mensal), format_brl(q.franquia))
                b.lit("Posso explicar coberturas, franquia e carência, ou chamar um colega se "
                      "preferir.")
            else:
                b.lit("Não tenho essa informação nesta cotação. Posso chamar um colega para ajudar.")
            return
        for t in topics:
            if t == "franquia":
                b.val("A franquia do plano {} é {}.", q.plano_nome, format_brl(q.franquia))
            elif t == "carencia":
                if q.carencia.coberturas:
                    b.val(_join([_label(c) for c in q.carencia.coberturas]).capitalize()
                          + " só passam a valer {} dias após o início da vigência.",
                          str(q.carencia.dias))
                else:
                    b.lit("Esta cotação não tem coberturas com carência.")
            elif t == "prorata":
                if q.pro_rata is not None:
                    p = q.pro_rata
                    b.val("Primeiro pagamento proporcional: {} de {} dias, {}. Os meses seguintes "
                          "são de {}.", str(p.dias_cobrados), str(p.dias_no_mes),
                          format_brl(p.valor_primeiro_pagamento), format_brl(q.premio_mensal))
                else:
                    b.lit("Não tenho informação de pro-rata nesta cotação. Posso chamar um colega "
                          "para ajudar.")
            elif t == "coberturas":
                b.val("O plano {} cobre: " + _join([_label(c) for c in q.coberturas]) + ".",
                      q.plano_nome)
            elif t.startswith("cob:"):
                cid = t[4:]
                if cid in q.coberturas:
                    b.val("Sim, o plano {} cobre " + _label(cid) + ".", q.plano_nome)
                    if cid in q.carencia.coberturas:
                        b.val("Lembrando: " + _join([_label(c) for c in q.carencia.coberturas])
                              + " só passam a valer {} dias após o início da vigência.",
                              str(q.carencia.dias))
                else:
                    b.val("O plano {} não inclui " + _label(cid) + " nesta cotação.", q.plano_nome)


class _MissingData(Exception):
    pass
