"""T-05: apresentacao com valores exatos e invariante de preco."""
import random
import re
from decimal import Decimal

import pytest

from autoseguro_agent.contracts import (
    Action,
    Carencia,
    Decision,
    HandoffReason,
    MessageType,
    OutboundKind as K,
    ProRata,
    QuoteResponse,
    State,
)
from autoseguro_agent.presentation import Frame, Presenter, PresentationView, format_brl, numbers_ok

pytestmark = [pytest.mark.unit, pytest.mark.req("RF-07", "RF-10", "RF-11", "RF-12", "RF-13", "RF-14",
                                                "RF-15", "RF-17", "RF-18", "RNF-03")]
P = Presenter()


def resp(plan="completo", premio="209.90", franquia="3000", pr=None, car=("roubo", "furto")):
    cob = ["colisao", "roubo", "furto", "terceiros", "vidros"]
    return QuoteResponse(plan, plan.capitalize(), Decimal(premio), Decimal(franquia), tuple(cob),
                         Carencia(tuple(car), 30, "obs"), "BRL", pr)


def dec(action, **params):
    return Decision(action, State.COTACAO_APRESENTADA, "T", None, params)


def test_format_brl():
    assert format_brl(Decimal("209.9")) == "R$ 209,90"
    assert format_brl(Decimal("1234.5")) == "R$ 1.234,50"
    assert format_brl(Decimal(3000)) == "R$ 3.000,00"
    assert format_brl(Decimal("0.005")) == "R$ 0,01"
    with pytest.raises(TypeError):
        format_brl(209.9)  # type: ignore[arg-type]


def test_quote_presented_contains_exact_fields():
    r = P.render(dec(Action.PRESENT), PresentationView(last_quote=resp(), quote_id="q-1"))
    t = r.text
    assert r.kind is K.QUOTE_PRESENTED and r.quote_id == "q-1" and r.guard_violation is None
    for s in ("Plano Completo", "R$ 209,90", "R$ 3.000,00", "colisão", "terceiros", "vidros",
              "Roubo e furto só passam a valer 30 dias", "cotação, sujeita a confirmação"):
        assert s in t, s
    assert "garantid" not in t.lower() and "emitid" not in t.lower()
    assert "Primeiro pagamento" not in t


def test_pro_rata_included():
    pr = ProRata(30, 16, Decimal("111.95"))
