"""Auditoria de log (T-13): ids, status, tentativas, preco com origem, motivos, fim (RFC 0005 4.7)."""
from __future__ import annotations

import json
import re
import sys
from decimal import Decimal
from pathlib import Path

REASONS = {"quote_indisponivel", "pedido_humano", "intencao_contratar", "sinistro_reclamacao",
           "objecao_fora_de_alcance", "dados_insuficientes", "erro_interno"}
AMOUNT = re.compile(r"R\$ ([\d.]+,\d{2})")


def _dec(s: str) -> Decimal:
    return Decimal(s.replace(".", "").replace(",", "."))


def audit(records: list[dict]) -> list[str]:
    bad: list[str] = []
    ok_quotes: dict[str, set[Decimal]] = {}
    last_seq = 0
    convs: set[str] = set()
    ended: set[str] = set()
    for i, r in enumerate(records, 1):
        if r.get("seq", 0) <= last_seq:
            bad.append(f"linha {i}: seq nao monotonico")
        last_seq = r.get("seq", 0)
        convs.add(r.get("conversation_id", ""))
        ev = r.get("event")
        if ev == "quote_result" and r.get("kind") == "ok":
            vals = {_dec(str(r[k])) for k in ("premio_mensal", "franquia", "valor_primeiro_pagamento")
                    if r.get(k)}
            ok_quotes[r["quote_id"]] = vals
        if ev == "conversation_end":
            ended.add(r["conversation_id"])
    for i, r in enumerate(records, 1):
        ev = r.get("event")
        if ev == "message":
            if not r.get("message_id") or not r.get("status"):
                bad.append(f"linha {i}: mensagem sem message_id/status (M-07)")
            if r.get("direction") == "out":
                amounts = AMOUNT.findall(r.get("text_masked") or "")
                if amounts:
                    qid = r.get("quote_id")
                    if not qid:
                        bad.append(f"linha {i}: preco sem quote_id (M-02)")
                    elif qid not in ok_quotes:
                        bad.append(f"linha {i}: quote_id sem resposta 200 (M-02)")
                    else:
                        for a in amounts:
                            if _dec(a) not in ok_quotes[qid]:
                                bad.append(f"linha {i}: valor diferente da resposta da API (M-01)")
        elif ev == "quote_attempt":
            for k in ("quote_id", "attempt", "latency_ms", "outcome"):
                if r.get(k) is None:
                    bad.append(f"linha {i}: quote_attempt sem {k}")
            if r.get("http_status") is None and not r.get("failure_kind"):
                bad.append(f"linha {i}: quote_attempt sem http_status nem failure_kind")
        elif ev == "handoff":
            if r.get("motivo") not in REASONS:
                bad.append(f"linha {i}: motivo de handoff fora da lista (M-06)")
    for c in convs - ended:
        bad.append(f"conversa {c}: sem conversation_end (RF-39)")
    return bad


def main(argv: list[str]) -> int:
    if len(argv) != 1:
        print("uso: audit_logs.py <log.jsonl>", file=sys.stderr)
        return 2
    path = Path(argv[0])
    if not path.exists():
        print(f"arquivo ausente: {path}", file=sys.stderr)
        return 2
    try:
        recs = [json.loads(x) for x in path.read_text(encoding="utf-8").splitlines() if x.strip()]
    except json.JSONDecodeError as exc:
        print(f"JSON invalido: {exc}", file=sys.stderr)
        return 1
    bad = audit(recs)
    for b in bad:
        print("VIOLACAO:", b, file=sys.stderr)
    print(f"audit_logs: {len(recs)} eventos, {len(bad)} violacoes")
    return 1 if bad else 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
