"""Verificacao pre-publicacao (T-11): dados pessoais, segredos, dados do autor, historico git.

uso: prepublish_check.py [--root .] [--history] [--allowlist ARQ] [--files F ...]
codigos de saida: 0 ok, 1 violacao, 2 erro de uso. O relatorio mostra hash curto, nunca o trecho.
"""
from __future__ import annotations

import argparse
import fnmatch
import hashlib
import os
import re
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from secret_patterns import HOME_PATH, SECRET_FILES, SECRETS  # noqa: E402

from autoseguro_agent.privacy.patterns import ORDER  # noqa: E402

MAX_BYTES = 5 * 1024 * 1024
EMAIL = ORDER[0][1][0]


def _h(s: str) -> str:
    return hashlib.sha1(s.encode("utf-8", "ignore")).hexdigest()[:8]


def load_allowlist(path: Path | None) -> list[str]:
    if path is None or not path.exists():
        return []
    out = []
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.split("#", 1)[0].strip()
        if line:
            out.append(line)
    return out


def allowed(rel: str, patterns: list[str]) -> bool:
    return any(fnmatch.fnmatch(rel, p) for p in patterns)


def scan_text(rel: str, text: str, terms: list[str]) -> list[tuple[str, str, int, str]]:
    """Devolve (severidade, tipo, linha, hash)."""
    found: list[tuple[str, str, int, str]] = []
    is_log = rel.startswith(("logs/", "ai-logs/")) or "/logs/" in rel or "/ai-logs/" in rel
    is_ai = rel.startswith("ai-logs/") or "/ai-logs/" in rel
    for ln, line in enumerate(text.splitlines(), 1):
        for kind, pats in ORDER:
            for p in pats:
                for m in p.finditer(line):
                    sev = "AVISO" if kind == "cep" and not is_log else "ERRO"
                    found.append((sev, kind, ln, _h(m.group(0))))
        for name, p in SECRETS.items():
            for m in p.finditer(line):
                found.append(("ERRO", f"segredo:{name}", ln, _h(m.group(0))))
        if is_ai:
            for m in HOME_PATH.finditer(line):
                found.append(("ERRO", "caminho_pessoal", ln, _h(m.group(0))))
            low = line.lower()
            for t in terms:
                if t and t.lower() in low:
                    found.append(("ERRO", "termo_do_autor", ln, _h(t)))
    return found


def git(root: Path, *args: str, check=True) -> bytes:
    r = subprocess.run(["git", *args], cwd=root, capture_output=True)
    if check and r.returncode != 0:
        raise RuntimeError(r.stderr.decode(errors="ignore").strip())
    return r.stdout


def tracked_files(root: Path) -> list[str]:
    out = git(root, "ls-files", "--cached", "--others", "--exclude-standard", "-z")
    return [p for p in out.decode("utf-8", "ignore").split("\0") if p]


def is_text(data: bytes) -> bool:
    return b"\0" not in data[:8192]


def scan_history(root: Path, patterns: list[str], terms: list[str]):
    out = git(root, "rev-list", "--objects", "--all").decode("utf-8", "ignore")
    seen: dict[str, str] = {}
    for line in out.splitlines():
        parts = line.split(" ", 1)
        if len(parts) == 2 and parts[0] not in seen:
            seen[parts[0]] = parts[1]
    findings = []
    for oid, path in seen.items():
        if allowed(path, patterns):
            continue
        typ = git(root, "cat-file", "-t", oid).decode().strip()
        if typ != "blob":
            continue
        data = git(root, "cat-file", "blob", oid)
        if len(data) > MAX_BYTES or not is_text(data):
            continue
        for f in scan_text(path, data.decode("utf-8", "ignore"), terms):
            findings.append((f"historico:{path}@{oid[:8]}", *f))
        if SECRET_FILES.search(path):
            findings.append((f"historico:{path}@{oid[:8]}", "ERRO", "arquivo_de_segredo", 0, _h(path)))
    return findings


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=".")
    ap.add_argument("--history", action="store_true")
    ap.add_argument("--allowlist", default=str(Path(__file__).with_name("prepublish_allowlist.txt")))
    ap.add_argument("--files", nargs="*", default=None,
                    help="varre so estes arquivos (modo demo); sem checagem de presenca")
    a = ap.parse_args(argv)
    root = Path(a.root).resolve()
    patterns = load_allowlist(Path(a.allowlist))
    terms_file = os.environ.get("AGENT_PERSONAL_TERMS_FILE")
    terms: list[str] = []
    if terms_file and Path(terms_file).exists():
        terms = [t.strip() for t in Path(terms_file).read_text(encoding="utf-8").splitlines() if t.strip()]
    else:
        print("[aviso] AGENT_PERSONAL_TERMS_FILE nao definido: termos do autor nao verificados",
              file=sys.stderr)

    findings: list[tuple[str, str, str, int, str]] = []
    try:
        if a.files is not None:
            files = [Path(f) for f in a.files]
            for f in files:
                rel = f.name
                if not f.exists():
                    print(f"arquivo ausente: {f}", file=sys.stderr)
                    return 2
                for sev, kind, ln, h in scan_text("logs/" + rel, f.read_text(encoding="utf-8"), terms):
                    findings.append((str(f), sev, kind, ln, h))
        else:
            for rel in tracked_files(root):
                p = root / rel
                if allowed(rel, patterns) or not p.is_file():
                    continue
                if SECRET_FILES.search(rel):
                    findings.append((rel, "ERRO", "arquivo_de_segredo", 0, _h(rel)))
                    continue
                if p.stat().st_size > MAX_BYTES:
                    continue
                data = p.read_bytes()
                if not is_text(data):
                    continue
                for sev, kind, ln, h in scan_text(rel, data.decode("utf-8", "ignore"), terms):
                    findings.append((rel, sev, kind, ln, h))
            ai = root / "ai-logs"
            if not ai.is_dir() or not any(f.is_file() and f.stat().st_size > 0 for f in ai.rglob("*")):
                findings.append(("ai-logs/", "ERRO", "ai-logs ausente ou vazio (RNF-12)", 0, "-"))
            cand = root / "README-candidato.md"
            if not cand.exists() or "ai-logs" not in cand.read_text(encoding="utf-8"):
                findings.append(("README-candidato.md", "AVISO",
                                 "README do candidato ausente ou sem mencao a ai-logs", 0, "-"))
        if a.history and a.files is None:
            findings += scan_history(root, patterns, terms)
    except (RuntimeError, OSError) as exc:
        print(f"erro de uso: {exc}", file=sys.stderr)
        return 2

    errors = [f for f in findings if f[1] == "ERRO"]
    for loc, sev, kind, ln, h in sorted(findings):
        print(f"{sev} {loc}:{ln} {kind} #{h}", file=sys.stderr if sev == "ERRO" else sys.stdout)
    print(f"prepublish_check: {len(errors)} erros, {len(findings) - len(errors)} avisos")
    return 1 if errors else 0


if __name__ == "__main__":
    raise SystemExit(main())
