"""Sanitiza sessoes de IA para ai-logs/ (D-08, RFC 0005 4.8, ADR 0027).

uso: sanitize_ailogs.py --src PASTA --dst ai-logs [--terms ARQ] [--recursive]
Copia *.jsonl (nao o diretorio memory/), substitui nos VALORES string: segredos, termos do autor,
caminhos pessoais, e-mails e dados pessoais. Mantem JSON valido; idempotente.
"""
from __future__ import annotations

import argparse
import json
import re
import sys
from collections import Counter
from datetime import date
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from secret_patterns import HOME_PATH, SECRETS  # noqa: E402

from autoseguro_agent.privacy.patterns import ORDER, PLACEHOLDERS  # noqa: E402


class Sanitizer:
    def __init__(self, terms: list[str]):
        self.terms = [t for t in terms if t.strip()]
        self.counts: Counter[str] = Counter()

    def text(self, s: str) -> str:
        for name, p in SECRETS.items():
            s, n = p.subn("[SEGREDO]", s)
            self.counts["segredo"] += n
        for t in self.terms:
            s, n = re.subn(re.escape(t), "[AUTOR]", s, flags=re.IGNORECASE)
            self.counts["termo_do_autor"] += n
        s, n = HOME_PATH.subn("~", s)
        self.counts["caminho_pessoal"] += n
        for kind, pats in ORDER:
            for p in pats:
                s, n = p.subn(PLACEHOLDERS[kind], s)
                self.counts[kind] += n
        return s

    def value(self, v):
        if isinstance(v, str):
            return self.text(v)
        if isinstance(v, list):
            return [self.value(x) for x in v]
        if isinstance(v, dict):
            return {k: self.value(x) for k, x in v.items()}
        return v

    def line(self, raw: str) -> str:
        if not raw.strip():
            return raw
        try:
            return json.dumps(self.value(json.loads(raw)), ensure_ascii=False)
        except json.JSONDecodeError:
            self.counts["linha_nao_json"] += 1
            return self.text(raw)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--src", required=True)
    ap.add_argument("--dst", required=True)
    ap.add_argument("--terms")
    ap.add_argument("--recursive", action="store_true")
    a = ap.parse_args(argv)
    src, dst = Path(a.src).expanduser(), Path(a.dst)
    if not src.is_dir():
        print(f"origem inexistente: {src}", file=sys.stderr)
        return 2
    files = sorted(src.rglob("*.jsonl") if a.recursive else src.glob("*.jsonl"))
    files = [f for f in files if "memory" not in f.relative_to(src).parts]
    if not files:
        print("nenhuma sessao .jsonl encontrada; destino nao alterado", file=sys.stderr)
        return 2
    terms = []
    if a.terms and Path(a.terms).expanduser().exists():
        terms = Path(a.terms).expanduser().read_text(encoding="utf-8").splitlines()
    elif a.terms:
        print(f"[aviso] arquivo de termos ausente: {a.terms}", file=sys.stderr)
    dst.mkdir(parents=True, exist_ok=True)
    san = Sanitizer(terms)
    for f in files:
        out = dst / f.relative_to(src)
        out.parent.mkdir(parents=True, exist_ok=True)
        with f.open(encoding="utf-8") as fin, out.open("w", encoding="utf-8") as fout:
            for raw in fin:
