                    and node.func.attr == "req"):
                for arg in node.args:
                    if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
                        ids.add(arg.value)
    return ids


def main(argv: list[str] | None = None) -> int:
    prd = Path(argv[0]) if argv else PRD
    tests = Path(argv[1]) if argv and len(argv) > 1 else AGENT / "tests"
    if not prd.exists():
        print(f"PRD ausente: {prd}", file=sys.stderr)
        return 2
    want, have = prd_ids(prd), test_req_ids(tests)
    # requisitos de documentacao/manual (T-12, README) ficam em tests/unit/test_manual_checklist.py
    missing = sorted(want - have, key=lambda x: (x.startswith("RNF"), int(x.split("-")[1])))
    unknown = sorted(have - want)
    for m in missing:
        print(f"SEM TESTE: {m}", file=sys.stderr)
    for u in unknown:
        print(f"ID INEXISTENTE no PRD: {u}", file=sys.stderr)
    print(f"check_traceability: {len(want)} requisitos, {len(missing)} sem teste, "
          f"{len(unknown)} ids desconhecidos")
    return 1 if (missing or unknown) else 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
